"""Topology classes for Mininet-style network emulation."""


class Topo:
    """Base topology: an abstract description of hosts, switches, and links."""

    def __init__(self):
        """Create an empty topology."""
        self._hosts = []
        self._switches = []
        self._links = []

    def addHost(self, name, **opts):
        """Add a host to the topology and return its name."""
        self._hosts.append(name)
        return name

    def addSwitch(self, name, **opts):
        """Add a switch to the topology and return its name."""
        self._switches.append(name)
        return name

    def addLink(self, node1, node2, **opts):
        """Add a link between two node names, storing link options."""
        self._links.append((node1, node2, opts))

    def hosts(self):
        """Return the list of host names in this topology."""
        return list(self._hosts)

    def switches(self):
        """Return the list of switch names in this topology."""
        return list(self._switches)

    def links(self):
        """Return the list of (node1, node2, opts) link tuples."""
        return list(self._links)

    def nodes(self):
        """Return all node names (hosts and switches)."""
        return self._hosts + self._switches


class LinearTopo(Topo):
    """Linear topology: k switches in a chain, one host per switch."""

    def __init__(self, k=2, **opts):
        """Build h1-s1-s2-...-sk-hk."""
        super().__init__()
        for i in range(1, k + 1):
            self.addSwitch(f"s{i}")
            self.addHost(f"h{i}")
        for i in range(1, k + 1):
            self.addLink(f"h{i}", f"s{i}", **opts)
            if i < k:
                self.addLink(f"s{i}", f"s{i + 1}", **opts)


class SingleSwitchTopo(Topo):
    """Single switch connected to k hosts."""

    def __init__(self, k=2, **opts):
        """Build one switch s1 with hosts h1..hk attached."""
        super().__init__()
        self.addSwitch("s1")
        for i in range(1, k + 1):
            self.addHost(f"h{i}")
            self.addLink(f"h{i}", "s1", **opts)


class TreeTopo(Topo):
    """Tree of switches with the given depth and fanout; hosts at the leaves."""

    def __init__(self, depth=1, fanout=2, **opts):
        """Build a tree with fanout**depth hosts and sum(fanout**i) switches."""
        super().__init__()
        self._host_count = 0
        self._switch_count = 0
        self._add_tree(depth, fanout, parent=None, opts=opts)

    def _add_tree(self, depth, fanout, parent, opts):
        """Recursively add a subtree: a switch with fanout children."""
        if depth == 0:
            self._host_count += 1
            host = self.addHost(f"h{self._host_count}")
            self.addLink(parent, host, **opts)
            return
        self._switch_count += 1
        switch = self.addSwitch(f"s{self._switch_count}")
        if parent is not None:
            self.addLink(parent, switch, **opts)
        for _ in range(fanout):
            self._add_tree(depth - 1, fanout, parent=switch, opts=opts)

