"""Service Function Chain (SFC) modeling with VNFs and link parameters."""


class VNF:
    """Virtual network function with processing delay and throughput overhead."""

    def __init__(self, name, processing_delay_ms=0.0, overhead_pct=0.0):
        """Create a VNF with a name, processing delay, and overhead percentage."""
        self.name = name
        self.processing_delay_ms = processing_delay_ms
        self.overhead_pct = overhead_pct

    @property
    def throughput_factor(self):
        """Fraction of throughput retained after passing through this VNF."""
        return 1.0 - self.overhead_pct / 100.0

    def __repr__(self):
        return f"VNF({self.name!r})"


class ServiceFunctionChain:
    """A chain of VNFs traversed by traffic between a client and a server."""

    def __init__(self, vnfs=None, link_bw=1000.0, link_delay=0.0):
        """Create an SFC from a list of VNFs and per-link parameters."""
        self.vnfs = list(vnfs) if vnfs else []
        self.link_bw = link_bw
        self.link_delay = link_delay

    def add_vnf(self, vnf):
        """Append a VNF to the end of the chain."""
        self.vnfs.append(vnf)

    @property
    def num_links(self):
        """Number of links in the chain (includes client and server links)."""
        return len(self.vnfs) + 1

    def compute_throughput(self):
        """End-to-end throughput: link bandwidth times all VNF factors."""
        throughput = self.link_bw
        for vnf in self.vnfs:
            throughput *= vnf.throughput_factor
        return throughput

    def compute_latency(self):
        """End-to-end latency: link delays plus VNF processing delays."""
        latency = self.num_links * self.link_delay
        latency += sum(vnf.processing_delay_ms for vnf in self.vnfs)
        return latency

