"""Containernet engine: Mininet extended with Docker container hosts."""

from netsim.container import DockerHost
from netsim.net import Mininet
from netsim.utils import jains_fairness_index


class Containernet(Mininet):
    """Emulated network supporting Docker container hosts alongside hosts."""

    def addDocker(self, name, image="ubuntu:latest", cls=DockerHost, **params):
        """Add a Docker container host to the network and return it."""
        host = cls(name, image=image, **params)
        self.hosts.append(host)
        self._nodes[name] = host
        self.graph.add_node(name)
        return host

    def docker_hosts(self):
        """Return the list of Docker container hosts in the network."""
        return [h for h in self.hosts if getattr(h, "is_container", False)]

    def compute_resource_fairness(self):
        """Jain's fairness index over the CPU share allocations of all hosts."""
        shares = [getattr(h, "cpu_shares", 0) for h in self.hosts]
        return jains_fairness_index(shares)

    def total_nodes(self):
        """Total number of nodes (hosts plus switches) in the network."""
        return len(self.hosts) + len(self.switches)

    def startup_overhead_ratio(self):
        """Ratio of Docker container startup time to plain host startup time."""
        return DockerHost.STARTUP_OVERHEAD_MS / DockerHost.HOST_STARTUP_MS

