"""P4-programmable data plane simulation.

Models P4 pipeline stages (parser, match-action tables, deparser), counters,
and multicast groups on top of the core Mininet switch infrastructure.
"""

from netsim.node import Switch
from netsim.topo import Topo


class P4MatchActionTable:
    """A named match-action table with configurable match fields and actions."""

    def __init__(self, name, match_fields, max_size=1024):
        """Create a table with a name, match field names, and a max size."""
        self.name = name
        self.match_fields = list(match_fields)
        self.max_size = max_size
        self._rules = []

    def add_rule(self, match_dict, action_name, action_params=None, priority=0):
        """Add a rule; return False if the table is full."""
        if len(self._rules) >= self.max_size:
            return False
        self._rules.append({
            "match": dict(match_dict),
            "action_name": action_name,
            "action_params": dict(action_params) if action_params else {},
            "priority": priority,
        })
        return True

    def lookup(self, packet_headers):
        """Return the best-matching rule (highest priority wins) or None."""
        best = None
        for rule in self._rules:
            if all(packet_headers.get(field) == value
                   for field, value in rule["match"].items()):
                if best is None or rule["priority"] > best["priority"]:
                    best = rule
        return best

    def delete_rule(self, match_dict):
        """Remove the rule with exactly the given match fields."""
        self._rules = [r for r in self._rules if r["match"] != dict(match_dict)]

    def size(self):
        """Return the current number of rules in the table."""
        return len(self._rules)

    def clear(self):
        """Remove all rules from the table."""
        self._rules = []


class P4Parser:
    """Extracts header fields from raw packet data.

    header_defs maps each field name to (offset, length) in bytes.
    """

    def __init__(self, header_defs):
        """Create a parser from {field_name: (offset, length)} definitions."""
        self.header_defs = dict(header_defs)

    def header_length(self):
        """Total byte length covered by the defined headers."""
        if not self.header_defs:
            return 0
        return max(offset + length
                   for offset, length in self.header_defs.values())

    def parse(self, packet_data):
        """Extract header fields from raw bytes into a dict of ints."""
        headers = {}
        for field, (offset, length) in self.header_defs.items():
            chunk = packet_data[offset:offset + length]
            headers[field] = int.from_bytes(chunk, "big")
        return headers

    def is_valid(self, packet_data):
        """Check if the packet has the minimum required length."""
        return len(packet_data) >= self.header_length()


class P4Deparser:
    """Reassembles packets from modified header fields."""

    def __init__(self, header_defs):
        """Create a deparser from {field_name: (offset, length)} definitions."""
        self.header_defs = dict(header_defs)

    def deparse(self, headers, payload):
        """Rebuild packet bytes from header field values plus payload."""
        header_len = max((offset + length
                          for offset, length in self.header_defs.values()),
                         default=0)
        data = bytearray(header_len)
        for field, (offset, length) in self.header_defs.items():
            value = headers.get(field, 0)
            data[offset:offset + length] = int(value).to_bytes(length, "big")
        return bytes(data) + bytes(payload)


class P4Counter:
    """Per-flow packet and byte counting over a fixed-size counter array."""

    def __init__(self, name, size):
        """Create a counter array with a name and number of entries."""
        self.name = name
        self.size = size
        self._packets = [0] * size
        self._bytes = [0] * size

    def increment(self, index, packet_bytes):
        """Increment packet count and byte count at the given index."""
        self._packets[index] += 1
        self._bytes[index] += packet_bytes

    def read(self, index):
        """Return the (packets, bytes) tuple at the given index."""
        return (self._packets[index], self._bytes[index])

    def reset(self, index=None):
        """Reset one counter, or all counters when index is None."""
        if index is None:
            self._packets = [0] * self.size
            self._bytes = [0] * self.size
        else:
            self._packets[index] = 0
            self._bytes[index] = 0

    def total_packets(self):
        """Sum of all packet counts."""
        return sum(self._packets)

    def total_bytes(self):
        """Sum of all byte counts."""
        return sum(self._bytes)


class P4Switch(Switch):
    """Switch with a programmable P4 pipeline (parse -> tables -> deparse)."""

    def __init__(self, name, program=None, **params):
        """Create a P4 switch with an optional P4 program name."""
        super().__init__(name, **params)
        self.program = program
        self.tables = {}
        self.counters = {}
        self.parser = None
        self.deparser = None

    def add_table(self, table):
        """Register a P4MatchActionTable in the pipeline."""
        self.tables[table.name] = table

    def add_counter(self, counter):
        """Register a P4Counter."""
        self.counters[counter.name] = counter

    def set_parser(self, parser):
        """Set the parser stage."""
        self.parser = parser

    def set_deparser(self, deparser):
        """Set the deparser stage."""
        self.deparser = deparser

    def get_table(self, name):
        """Get a table by name."""
        return self.tables.get(name)

    def get_counter(self, name):
        """Get a counter by name."""
        return self.counters.get(name)

    @property
    def pipeline_latency_us(self):
        """Pipeline latency: 0.5us per table in the pipeline."""
        return 0.5 * len(self.tables)

    def process_packet(self, packet_data):
        """Run the full pipeline: parse -> match-action tables -> deparse.

        Returns the processed packet bytes, or None if the packet is dropped
        by a matched 'drop' action or fails to parse. Matched action params
        whose keys are header fields update those fields before deparsing.
        """
        if self.parser is None or not self.parser.is_valid(packet_data):
            return None
        headers = self.parser.parse(packet_data)
        for table in self.tables.values():
            rule = table.lookup(headers)
            if rule is None:
                continue
            if rule["action_name"] == "drop":
                return None
            for field, value in rule["action_params"].items():
                if field in headers:
                    headers[field] = value
        if self.deparser is None:
            return packet_data
        payload = packet_data[self.parser.header_length():]
