from collections import defaultdict

from netsim.graph import WeightedGraph


class FlowRule:
    """OpenFlow-style flow entry with match fields, actions, and timeouts."""

    def __init__(self, match_fields, actions, priority=100, idle_timeout=0,
                 hard_timeout=0):
        """Create a flow rule.

        match_fields is a dict (e.g. {"dst_ip": "10.0.0.1", "in_port": 1});
        actions is a list of dicts (e.g. [{"type": "output", "port": 2}]).
        idle_timeout/hard_timeout are in seconds (0 = permanent).
        """
        self.match_fields = dict(match_fields)
        self.actions = list(actions)
        self.priority = priority
        self.idle_timeout = idle_timeout
        self.hard_timeout = hard_timeout
        self.packet_count = 0
        self.byte_count = 0
        self.install_time = 0.0

    def is_expired(self, current_time, last_matched_time):
        """Return True if the rule expired by idle or hard timeout."""
        if self.hard_timeout > 0 and \
                current_time - self.install_time >= self.hard_timeout:
            return True
        if self.idle_timeout > 0 and \
                current_time - last_matched_time >= self.idle_timeout:
            return True
        return False

    def matches(self, packet_headers):
        """Return True if every match field equals the packet header value."""
        return all(packet_headers.get(field) == value
                   for field, value in self.match_fields.items())

    def __repr__(self):
        return (f"FlowRule({self.match_fields!r}, priority={self.priority})")


class FlowTable:
    """Per-switch flow table with bounded capacity."""

    def __init__(self, switch_name, capacity=4096):
        """Create a flow table for the named switch."""
        self.switch_name = switch_name
        self.capacity = capacity
        self._rules = []

    def install(self, rule):
        """Install a FlowRule; return False if the table is at capacity.

        An existing rule with identical match fields is replaced.
        """
        for i, existing in enumerate(self._rules):
            if existing.match_fields == rule.match_fields:
                self._rules[i] = rule
                return True
        if len(self._rules) >= self.capacity:
            return False
        self._rules.append(rule)
        return True

    def remove(self, match_fields):
        """Remove the rule matching the given match fields; return count."""
        before = len(self._rules)
        self._rules = [r for r in self._rules
                       if r.match_fields != match_fields]
        return before - len(self._rules)

    def lookup(self, packet_headers):
        """Return the highest-priority rule matching the packet, or None.

        Updates the matched rule's packet/byte counters.
        """
        matches = [r for r in self._rules if r.matches(packet_headers)]
        if not matches:
            return None
        rule = max(matches, key=lambda r: r.priority)
        rule.packet_count += 1
        rule.byte_count += packet_headers.get("size", 0)
        return rule

    def evict_expired(self, current_time, last_matched_times):
        """Evict expired rules; last_matched_times maps rule -> time.

        Rules missing from last_matched_times use their install_time.
        Returns the number of rules evicted.
        """
        kept = []
        evicted = 0
        for rule in self._rules:
            last = last_matched_times.get(rule, rule.install_time)
            if rule.is_expired(current_time, last):
                evicted += 1
            else:
                kept.append(rule)
        self._rules = kept
        return evicted

    def size(self):
        """Return the current number of rules."""
        return len(self._rules)

    def stats(self):
        """Return a list of (rule, packet_count, byte_count) tuples."""
        return [(r, r.packet_count, r.byte_count) for r in self._rules]

    def clear(self):
        """Remove all rules."""
        self._rules = []

    def utilization(self):
        """Return the size/capacity ratio."""
        return len(self._rules) / self.capacity


class SDNController:
    """Base SDN controller: topology graph plus per-switch flow tables."""

    def __init__(self, name):
        """Create a controller with an empty topology graph and flow tables."""
        self.name = name
        self.graph = WeightedGraph()
        self.flow_tables = {}
        self.hosts = []
        self._ip_to_host = {}
        self._ports = defaultdict(dict)
        self._installed_paths = {}

    def add_switch(self, switch_name):
        """Register a switch and create its FlowTable."""
        self.graph.add_node(switch_name)
        if switch_name not in self.flow_tables:
            self.flow_tables[switch_name] = FlowTable(switch_name)

    def add_link(self, node1, node2, weight=1):
        """Add a link to the topology graph, assigning port numbers."""
        self.graph.add_edge(node1, node2, weight=weight)
        if node2 not in self._ports[node1]:
            self._ports[node1][node2] = len(self._ports[node1]) + 1
        if node1 not in self._ports[node2]:
            self._ports[node2][node1] = len(self._ports[node2]) + 1

    def remove_link(self, node1, node2):
        """Remove a link from the topology graph (simulates failure)."""
        self.graph.remove_edge(node1, node2)
        self._ports[node1].pop(node2, None)
        self._ports[node2].pop(node1, None)

    def topology_discovery(self, net):
        """Build the topology graph and flow tables from a Mininet instance."""
        for switch in net.switches:
            self.add_switch(switch.name)
        for host in net.hosts:
            self.graph.add_node(host.name)
            self.hosts.append(host.name)
            if host.ip:
                self._ip_to_host[host.ip] = host.name
        for link in net.links:
            self.add_link(link.intf1.node.name, link.intf2.node.name)

    def compute_path(self, src, dst):
        """Dijkstra shortest path from src to dst; [] if disconnected."""
        path = self.graph.shortest_path(src, dst)
        return path if path is not None else []

    def compute_all_paths(self):
        """Compute paths between all ordered host pairs."""
        paths = {}
        for src in self.hosts:
            for dst in self.hosts:
                if src != dst:
                    paths[(src, dst)] = self.compute_path(src, dst)
        return paths

    def _edge_in_path(self, path, node1, node2):
        """Return True if the (undirected) edge node1-node2 is on the path."""
        return any({u, v} == {node1, node2}
                   for u, v in zip(path, path[1:]))

    def install_path_rules(self, path, src_ip, dst_ip, priority=100):
        """Install a forwarding rule on each switch along the path.

        Each rule matches (src_ip, dst_ip) and outputs towards the next hop.
        Returns the number of rules installed.
        """
        if not path:
            return 0
        installed = 0
        for i, node in enumerate(path):
            if node not in self.flow_tables:
                continue
            if i + 1 < len(path):
                out_port = self._ports[node].get(path[i + 1], 0)
            else:
                out_port = 0
            rule = FlowRule(
                {"src_ip": src_ip, "dst_ip": dst_ip},
                [{"type": "output", "port": out_port}],
                priority=priority,
            )
            if self.flow_tables[node].install(rule):
                installed += 1
        self._installed_paths[(src_ip, dst_ip)] = path
        return installed

    def total_rules_installed(self):
        """Return the sum of rules across all flow tables."""
        return sum(t.size() for t in self.flow_tables.values())

    def handle_link_failure(self, node1, node2):
        """Remove a failed link and reinstall rules for affected paths.

        Returns the number of rules reinstalled on new paths.
        """
        self.remove_link(node1, node2)
        reinstalled = 0
        for (src_ip, dst_ip), path in list(self._installed_paths.items()):
            if not self._edge_in_path(path, node1, node2):
                continue
            for node in path:
                if node in self.flow_tables:
                    self.flow_tables[node].remove(
                        {"src_ip": src_ip, "dst_ip": dst_ip})
            new_path = self.compute_path(path[0], path[-1])
            reinstalled += self.install_path_rules(new_path, src_ip, dst_ip)
        return reinstalled


class ReactiveController(SDNController):
    """Controller that installs rules on-demand in response to packet-in events."""

    PACKET_IN_TIME_MS = 0.05

    def __init__(self, name):
        """Create a reactive controller with a packet-in counter."""
        super().__init__(name)
        self.packet_in_count = 0

    def handle_packet_in(self, switch_name, packet_headers):
        """Handle a packet-in: on table miss, install rules along the path.

        Returns the computed path, or None if the packet is not routable.
        """
        self.packet_in_count += 1
        table = self.flow_tables.get(switch_name)
        if table is not None and table.lookup(packet_headers) is not None:
            return None
        src = self._ip_to_host.get(packet_headers.get("src_ip"))
        dst = self._ip_to_host.get(packet_headers.get("dst_ip"))
        if src is None or dst is None:
            return None
        path = self.compute_path(src, dst)
        self.install_path_rules(
            path, packet_headers["src_ip"], packet_headers["dst_ip"])
        return path


class ProactiveController(SDNController):
    """Controller that pre-installs forwarding rules for all host pairs."""

    rule_install_time_ms = 0.1

    def __init__(self, name):
        """Create a proactive controller with an installed-rule counter."""
        super().__init__(name)
        self._rules_installed = 0

    def install_all_rules(self, hosts_with_ips):
        """Install rules on all switches along the path of every src-dst pair.

        hosts_with_ips is an iterable of (host_name, ip) pairs.
        Returns the total number of rules installed.
        """
        entries = list(hosts_with_ips)
        for src_name, src_ip in entries:
            for dst_name, dst_ip in entries:
                if src_name == dst_name:
                    continue
                path = self.compute_path(src_name, dst_name)
                self._rules_installed += self.install_path_rules(
                    path, src_ip, dst_ip)
        return self._rules_installed

    def total_install_time(self):
        """Return the total simulated rule installation time in ms."""
        return self._rules_installed * self.rule_install_time_ms

